const body = $json.body || $json;
const message = String(body.message || '').toLowerCase();

let buyerStage = 'Discovery';
let recommendedReply = 'The fastest next step is a 15-minute automation audit call.';
let nextAction = 'SEND_GENERAL_SALES_REPLY';

if (message.includes('price') || message.includes('cost') || message.includes('budget')) {
  buyerStage = 'Pricing';
  recommendedReply = 'Projects typically start at $2,000 depending on complexity. The best next step is a quick automation audit so I can understand what you need and give you a realistic recommendation.';
  nextAction = 'SEND_PRICING_REPLY';
}

if (message.includes('book') || message.includes('call') || message.includes('schedule') || message.includes('meeting')) {
  buyerStage = 'Booking';
  recommendedReply = 'Great. The best next step is to book a quick 15-minute automation audit. Here is the booking link: INSERT_BOOKING_LINK_HERE';
  nextAction = 'SEND_BOOKING_LINK';
}

return [{
  json: {
    leadName: body.name || 'Unknown Prospect',
    email: body.email || '',
    company: body.company || '',
    originalMessage: body.message || '',
    buyerStage,
    nextAction,
    recommendedReply,
    assessedAt: new Date().toISOString()
  }
}];

const isBookingIntent = $json.nextAction === 'SEND_BOOKING_LINK';

return [{
  json: {
    ...$json,
    responseType: isBookingIntent ? 'BOOKING_LINK_RESPONSE' : 'SALES_REPLY_RESPONSE',
    sendStatus: 'READY_TO_SEND_PLACEHOLDER',
    message: isBookingIntent
      ? 'Replace this node with Gmail, Outlook, SMS, Slack, or CRM message sender to send the booking link.'
      : 'Replace this node with Gmail, Outlook, SMS, Slack, or CRM message sender to send the sales reply.'
  }
}];

return [{
  json: {
    workflowStatus: 'SALES_AGENT_RESPONSE_READY',
    processedAt: new Date().toISOString(),
    leadName: $json.leadName,
    email: $json.email,
    company: $json.company,
    buyerStage: $json.buyerStage,
    nextAction: $json.nextAction,
    recommendedReply: $json.recommendedReply,
    responseType: $json.responseType,
    sendStatus: $json.sendStatus
  }
}];
